{
  "table": {
    "name": "district",
    "purpose": "Demographic and socioeconomic statistics for 77 Czech districts (the classic PKDD'99 financial dataset). One row per district; referenced by clients and accounts as their home district."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "district_id",
      "description": "Primary key; sequential district identifier 1-77. Referenced by account and client tables.",
      "status": "resolved"
    },
    "col_002": {
      "role": "category",
      "name": "district_name",
      "description": "Name of the district (Czech town/district seat, e.g. 'Jablonec n. Nisou', 'Brno - mesto'). Unique per row.",
      "status": "resolved"
    },
    "col_003": {
      "role": "category",
      "name": "region",
      "description": "Czech region the district belongs to (8 values: Prague, central/north/south/east/west Bohemia, north/south Moravia).",
      "status": "resolved"
    },
    "col_004": {
      "role": "numeric",
      "name": "population",
      "description": "District population (42,821 to 1,204,953; Prague is the max outlier).",
      "status": "resolved"
    },
    "col_005": {
      "role": "numeric",
      "name": "municipalities_under_500",
      "description": "Count of municipalities in the district with fewer than 500 inhabitants (0-151).",
      "status": "resolved"
    },
    "col_006": {
      "role": "numeric",
      "name": "municipalities_500_1999",
      "description": "Count of municipalities with 500-1,999 inhabitants (0-70).",
      "status": "resolved"
    },
    "col_007": {
      "role": "numeric",
      "name": "municipalities_2000_9999",
      "description": "Count of municipalities with 2,000-9,999 inhabitants (0-20).",
      "status": "resolved"
    },
    "col_008": {
      "role": "numeric",
      "name": "municipalities_over_10000",
      "description": "Count of municipalities with more than 10,000 inhabitants (0-5).",
      "status": "resolved"
    },
    "col_009": {
      "role": "numeric",
      "name": "city_count",
      "description": "Small count 1-11 per district, likely the number of cities/towns in the district. Alternative reading: number of urban municipalities; the exact definition cannot be confirmed from values alone.",
      "status": "tentative"
    },
    "col_010": {
      "role": "numeric",
      "name": "urban_inhabitants_ratio",
      "description": "Share of population living in urban areas, in percent (33.9-100.0; Prague = 100).",
      "status": "resolved"
    },
    "col_011": {
      "role": "numeric",
      "name": "average_salary",
      "description": "Average monthly salary in the district, in CZK (8,110-12,541).",
      "status": "resolved"
    },
    "col_012": {
      "role": "numeric",
      "name": "unemployment_rate_1995",
      "description": "Unemployment rate in 1995, in percent (0.2-7.3; one null).",
      "status": "resolved"
    },
    "col_013": {
      "role": "numeric",
      "name": "unemployment_rate_1996",
      "description": "Unemployment rate in 1996, in percent (0.43-9.4); values slightly higher than the 1995 column, consistent with year-over-year rates.",
      "status": "resolved"
    },
    "col_014": {
      "role": "numeric",
      "name": "entrepreneurs_per_1000",
      "description": "Number of entrepreneurs per 1,000 inhabitants (81-167).",
      "status": "resolved"
    },
    "col_015": {
      "role": "numeric",
      "name": "crimes_1995",
      "description": "Number of committed crimes in 1995 (818-85,677; Prague is the outlier). One null.",
      "status": "resolved"
    },
    "col_016": {
      "role": "numeric",
      "name": "crimes_1996",
      "description": "Number of committed crimes in 1996 (888-99,107); values slightly higher than the 1995 column, consistent with year-over-year counts.",
      "status": "resolved"
    }
  }
}
